<script setup>
import {ref,reactive,watch,onMounted} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {fetchItems} from '../api';
import ItemCard from '../components/ItemCard.vue';
const route=useRoute(),router=useRouter(),list=ref([]),total=ref(0),loading=ref(true),error=ref('');
const filter=reactive({keyword:'',genre:'',annotation:'',sort:'latest',page:1});
const genres=[['','全部书籍'],['textbook','课程教材'],['exam','考试资料'],['reading','课外阅读'],['other','其他书籍']];
const notes=[['none','无笔记划线'],['light','少量笔记'],['heavy','较多笔记'],['unknown','待确认']];
const shortcuts=['高等数学','四六级','考研','计算机','文学阅读'];let revision=0;
function fromQuery(){filter.keyword=typeof route.query.keyword==='string'?route.query.keyword:'';filter.genre=genres.some(g=>g[0]===route.query.genre)?route.query.genre:'';filter.annotation=notes.some(n=>n[0]===route.query.annotation)?route.query.annotation:'';filter.sort=['latest','priceAsc','priceDesc'].includes(route.query.sort)?route.query.sort:'latest';filter.page=/^[1-9]\d*$/.test(route.query.page||'')?Number(route.query.page):1;}
async function load(){const own=++revision;loading.value=true;error.value='';try{const r=await fetchItems({kind:'book',...filter,pageSize:12});if(own!==revision)return;list.value=r.list;total.value=r.total;}catch{if(own===revision)error.value='暂时无法加载书架，请重试。';}finally{if(own===revision)loading.value=false;}}
async function apply(reset=true){if(reset)filter.page=1;const query={...(filter.keyword.trim()?{keyword:filter.keyword.trim()}:{}),...(filter.genre?{genre:filter.genre}:{}),...(filter.annotation?{annotation:filter.annotation}:{}),...(filter.sort!=='latest'?{sort:filter.sort}:{}),...(filter.page>1?{page:String(filter.page)}:{})};const target=router.resolve({name:'books',query});if(target.fullPath===route.fullPath)await load();else await router.push({name:'books',query});}
function reset(){Object.assign(filter,{keyword:'',genre:'',annotation:'',sort:'latest',page:1});apply();}
watch(()=>route.fullPath,()=>{fromQuery();load();});onMounted(()=>{fromQuery();load();});
</script>
<template><div class="page book-market"><div class="container">
 <section class="book-market-hero"><div><span class="eyebrow">SHIGUANG CAMPUS BOOK CLUB</span><h1>一本旧书，<br/>一次新的开始。</h1><p>找对版本，看清笔记，<br/>让上一位同学的书，陪你走下一段路。</p><RouterLink class="publish-button" :to="{name:'publish',query:{kind:'book'}}">我有旧书要出售</RouterLink></div><img :src="'/uploads/photos/books-table.jpg'" alt="桌上堆叠的真实旧书，授权场景示意"/><span class="book-market-stamp">READ IT.<br/>LOVE IT.<br/>PASS IT ON.</span></section>
 <div class="book-controls card"><form class="book-search" @submit.prevent="apply()"><el-icon><Search/></el-icon><input v-model="filter.keyword" aria-label="搜索二手书" placeholder="输入书名、作者、ISBN 或课程名称"/><button class="publish-button">找书</button></form><div class="book-shortcuts"><span>同学们常找</span><button v-for="word in shortcuts" :key="word" @click="filter.keyword=word;apply()">{{word}}</button></div><div class="book-filter-row"><div class="book-tabs"><button v-for="[key,label] in genres" :key="key" :class="{active:filter.genre===key}" @click="filter.genre=key;apply()">{{label}}</button></div><div class="book-selects"><el-select v-model="filter.annotation" aria-label="笔记程度" placeholder="全部笔记程度" clearable @change="apply()"><el-option v-for="[value,label] in notes" :key="value" :value="value" :label="label"/></el-select><el-select v-model="filter.sort" aria-label="书籍排序" @change="apply()"><el-option label="最新上架" value="latest"/><el-option label="价格从低到高" value="priceAsc"/><el-option label="价格从高到低" value="priceDesc"/></el-select><el-button text @click="reset">重置</el-button></div></div></div>
 <div class="section-heading"><h2>校园流转书架</h2><span class="text-sub">{{total}} 本在售 · 校内面交</span></div><div v-if="error" class="inline-error">{{error}}<el-button @click="load">重新加载</el-button></div><el-skeleton v-else-if="loading" :rows="8" animated/><div v-else-if="list.length" class="item-grid"><ItemCard v-for="item in list" :key="item.id" :item="item"/></div><div v-else class="quiet-empty"><h3>暂时没有找到这本书</h3><p>换个关键词，或放宽笔记程度试试。</p><el-button @click="reset">查看全部书籍</el-button></div><div class="book-pagination"><el-pagination v-if="total>12" v-model:current-page="filter.page" :page-size="12" :total="total" layout="prev,pager,next" @current-change="apply(false)"/></div><div class="book-trade-note"><el-icon><Reading/></el-icon><p>买书前，请向卖家确认版次、目录和笔记细节；卖书时，记得上传封面、版权页与内页实拍。</p></div>
 </div></div></template>
